function setup() {
  createCanvas(252, 164);
  pixelDensity(1)
  clear()
}

recv((m, {inlet}) => {
  if (inlet == 0) {
    stroke('pink');
    point(m[0], m[1]);
  } else {
    clear()
  }
})

// The Nature of Code
// Daniel Shiffman
// http://natureofcode.com

const [w, h] = [252, 164]

class Walker {
  nodes = []

  step() {
    for (let i in this.nodes) {
      const c = Math.floor(Math.random() * 4);
      let [x, y] = this.nodes[i]

      if (c == 0) x++;
      else if (c == 1) x--;
      else if (c == 2) y++;
      else y--;

      this.nodes[i] = [x, y]
    }
  }
}

const wk = new Walker()
const rand = (x) => Math.random() * x

recv(m => {
  if (m == 'clear') {
    wk.nodes = []
  } else if (m == 'add') {
    wk.nodes.push([rand(w), rand(h)])
  }
})

setInterval(() => {
  wk.step()

  for (let n of wk.nodes) send(n)
}, 1000/60)

setRunOnMount(true)
setTitle('add10')

for (let i=0; i<10; i++) {
  send({type: 'bang'})
}

setPortCount(1)

const reverb = new Tone.Reverb({
  decay: 2,
  wet: 0.3
}).connect(outputNode);

const synth = new Tone.PolySynth(Tone.Synth, {
  oscillator: {
    type: "fatsine",
    count: 1,
    spread: 3
  },
  envelope: {
    attack: 0.01,
    release: 0.9
  }
}).connect(reverb);

reverb.generate();

recv(m => {
  const now = Tone.now();

  if (m.type === 'noteOn') {
    const freq = Tone.Frequency(m.note, "midi").toNote();
    const velocity = m.velocity / 127;

    synth.triggerAttack(freq, now, velocity);
  } else if (m.type === 'noteOff') {
    const freq = Tone.Frequency(m.note, "midi").toNote();

    synth.triggerRelease(freq, now);
  } else if (m.type === 'pitchBend') {
    synth.set({ detune: m.value * 200 });
  }
})

return { 
  cleanup: () => {
    synth.dispose();
    reverb.dispose();
  } 
}
